#!/usr/bin/env python3
"""Measure a batch's own commits by category. Read-only on the repo."""
import subprocess, sys, os, re, json, collections

REPO = '/home/user/fortress'

def git(*args, check=True):
    r = subprocess.run(['git', '-C', REPO] + list(args), capture_output=True, text=True)
    if check and r.returncode != 0:
        raise RuntimeError(r.stderr)
    return r.stdout

COORD = {
    'explorations/coordinator/FACTS.md', 'explorations/coordinator/POSITIONS.md',
    'explorations/coordinator/PLAN.md', 'explorations/coordinator/INDEX.md',
    'explorations/fortress-gap-ledger.md', 'explorations/microgpt-run-c-handover.md',
}
CAPT = {'.txt', '.tsv', '.out', '.log', '.csv', '.json'}
PROBE = {'.fss', '.fsi', '.test'}
SCRIPT = {'.sh', '.py', '.js', '.java', '.scala', '.pl', '.rb', '.awk', '.mjs'}
BUILD = {'build.xml', 'ProjectFortress/build.xml', 'ProjectFortress/ant', 'build.properties'}

def category(p):
    if p in COORD:
        return 'COORDINATOR', ''
    if p.startswith('explorations/'):
        ext = os.path.splitext(p)[1]
        if ext == '.md': return 'RECORDS', 'REPORTS'
        if ext in CAPT: return 'RECORDS', 'CAPTURES'
        if ext in PROBE: return 'RECORDS', 'PROBES'
        if ext in SCRIPT: return 'RECORDS', 'SCRIPTS'
        return 'RECORDS', 'OTHER'
    if p.startswith('Library/') or p.startswith('ProjectFortress/LibraryBuiltin/'):
        return 'CODE', 'library'
    if p.startswith('ProjectFortress/src/') and p.endswith('.java'):
        return 'CODE', 'java'
    if p.startswith('ProjectFortress/src/') and p.endswith('.scala'):
        return 'CODE', 'scala'
    if p.startswith('ProjectFortress/astgen/'):
        return 'CODE', 'astgen'
    if os.path.basename(p) in ('build.xml',) or p in BUILD:
        return 'CODE', 'build'
    if p == 'Specification/fortress.pdf':
        return 'SPEC', 'pdf'
    if p.startswith('Specification/') and p.endswith('.tex'):
        return 'SPEC', 'tex'
    if p.startswith('ProjectFortress/') and re.search(r'(^|/)(tests|compiler_tests|library_tests|not_passing_yet|not_working_library_tests|[a-z_]*tests?)/', p):
        return 'TESTS', ''
    return 'OTHERTREE', ''

def numstat(c):
    out = git('show', '--numstat', '-M', '--format=', c)
    rows = []
    for line in out.splitlines():
        if not line.strip():
            continue
        a, d, path = line.split('\t', 2)
        old = new = path
        if '=>' in path:
            # rename forms: a/{x => y}/b or x => y
            m = re.match(r'(.*)\{(.*) => (.*)\}(.*)', path)
            if m:
                pre, o, n, post = m.groups()
                old = (pre + o + post).replace('//', '/')
                new = (pre + n + post).replace('//', '/')
            else:
                old, new = [s.strip() for s in path.split(' => ')]
        rows.append((a, d, old, new))
    return rows

def status(c):
    out = git('show', '--name-status', '-M', '--format=', c)
    st = {}
    for line in out.splitlines():
        parts = line.split('\t')
        if not parts or not parts[0]:
            continue
        s = parts[0]
        if s.startswith('R'):
            st[parts[2]] = ('R', parts[1])
        else:
            st[parts[1]] = (s, None)
    return st

def blob_size(rev, path):
    r = subprocess.run(['git', '-C', REPO, 'cat-file', '-s', f'{rev}:{path}'], capture_output=True, text=True)
    return int(r.stdout.strip()) if r.returncode == 0 else None

def blob_lines(rev, path):
    r = subprocess.run(['git', '-C', REPO, 'show', f'{rev}:{path}'], capture_output=True)
    if r.returncode != 0: return None
    return r.stdout.count(b'\n')

def main(name, commits, landing):
    per_file = collections.OrderedDict()  # path -> dict
    for c in commits:
        st = status(c)
        for a, d, old, new in numstat(c):
            a = int(a) if a != '-' else 0
            d = int(d) if d != '-' else 0
            s = st.get(new, ('?', None))[0]
            f = per_file.setdefault(new, {'add': 0, 'del': 0, 'statuses': [], 'commits': [], 'old': None})
            f['add'] += a; f['del'] += d
            f['statuses'].append(s[0]); f['commits'].append(c)
            if s == 'R': f['old'] = old
    res = {'name': name, 'files': {}}
    for p, f in per_file.items():
        cat, sub = category(p)
        f['cat'] = cat; f['sub'] = sub
        f['created'] = f['statuses'][0] == 'A'
        f['deleted_in_batch'] = f['statuses'][-1] == 'D'
        f['size_at_landing'] = blob_size(landing, p)
        f['size_at_head'] = blob_size('HEAD', p)
        f['lines_at_landing'] = blob_lines(landing, p)
        res['files'][p] = f
    json.dump(res, sys.stdout, indent=1)

if __name__ == '__main__':
    name = sys.argv[1]; landing = sys.argv[2]; commits = sys.argv[3:]
    main(name, commits, landing)

