def agg(pred):
    n = a = dl = b = 0
    for p, f in files.items():
        if pred(p, f):
            n += 1; a += f['add']; dl += f['del']
            b += (f['size_at_landing'] or 0)
    return n, a, dl, b

print('==', d['name'], 'files touched', len(files))
