    cats.setdefault((f['cat'], f['sub']), []).append(p)
for (c, s), ps in sorted(cats.items()):
    n, a, dl, b = agg(lambda p, f: (f['cat'], f['sub']) == (c, s))
    created = sum(1 for p in ps if files[p]['created'])
    print(f'{c:12s} {s:9s} files={n:4d} created={created:4d} +{a:6d} -{dl:5d} bytes_at_landing={b}')

print('-- CODE/SPEC/OTHERTREE files')
for p, f in files.items():
    if f['cat'] in ('CODE', 'SPEC', 'OTHERTREE'):
        print(f"  {f['cat']}/{f['sub']} +{f['add']} -{f['del']} {''.join(f['statuses'])} {p}")
print('-- TESTS files')
for p, f in files.items():
    if f['cat'] == 'TESTS':
        print(f"  +{f['add']} -{f['del']} {''.join(f['statuses'])} {p}" + (f" (from {f['old']})" if f['old'] else ''))
print('-- COORDINATOR')
