        print(f"  +{f['add']} -{f['del']} {p}  commits={len(f['commits'])}")
print('-- RECORDS deleted in batch or gone at HEAD')
for p, f in files.items():
    if f['cat'] == 'RECORDS' and (f['deleted_in_batch'] or f['size_at_head'] is None):
        print(f"  {''.join(f['statuses'])} headsize={f['size_at_head']} {p}")
print('-- RECORDS modified-not-created')
