        print(f"  +{f['add']} -{f['del']} {''.join(f['statuses'])} {p}")
print('-- RECORDS top 12 by lines added')
recs = sorted(((f['add'], f['size_at_landing'], p) for p, f in files.items() if f['cat'] == 'RECORDS'), reverse=True)
for a, b, p in recs[:12]:
    print(f'  {a:5d} {b} {p}')
print('-- RECORDS by top dir')
dirs = collections.Counter(); dl = collections.Counter(); dn = collections.Counter()
for p, f in files.items():
    if f['cat'] == 'RECORDS':
        parts = p.split('/')
        k = '/'.join(parts[:3]) if parts[1] == 'compile-ladder' else '/'.join(parts[:2])
        dn[k] += 1; dl[k] += f['add']; dirs[k] += (f['size_at_landing'] or 0)
for k in dn:
    print(f'  {k}: files={dn[k]} lines+={dl[k]} bytes={dirs[k]}')
print('-- RECORDS OTHER extensions')
ext = collections.Counter(); extl = collections.Counter()
for p, f in files.items():
    if f['cat'] == 'RECORDS' and f['sub'] == 'OTHER':
        e = os.path.splitext(p)[1] or os.path.basename(p)
        ext[e] += 1; extl[e] += f['add']
print('  ', dict(ext), dict(extl))
print('-- RECORDS empty files (0 bytes at landing)')
print('  ', sum(1 for p, f in files.items() if f['cat'] == 'RECORDS' and f['size_at_landing'] == 0))

