#!/usr/bin/env python3
"""Citation check of a batch's RECORDS files against tracked .md files at HEAD."""
import json, sys, os, subprocess, collections

REPO = '/home/user/fortress'
d = json.load(open(sys.argv[1]))
files = d['files']
verbose = len(sys.argv) > 2

tracked = subprocess.run(['git', 'ls-files'], capture_output=True, text=True, cwd=REPO).stdout.split('\n')
tracked = [t for t in tracked if t]
bn_count = collections.Counter(os.path.basename(t) for t in tracked)
mds = [t for t in tracked if t.endswith('.md')]
md_text = {}
for m in mds:
    try:
        md_text[m] = open(os.path.join(REPO, m), encoding='utf-8', errors='replace').read()
    except FileNotFoundError:
        pass

COMMON_MD = {'README.md', 'REPORT.md', 'record.md', 'RECORD.md', 'SKEPTIC.md', 'JUDGE.md'}

def unit_dir(p):
    parts = p.split('/')
    if len(parts) > 3 and parts[1] == 'compile-ladder':
        return '/'.join(parts[:3])
    if len(parts) > 2:
        return '/'.join(parts[:2])
    return os.path.dirname(p)

def any_md(needle, exclude=(), within=None):
    hits = []
    for m, t in md_text.items():
        if m in exclude: continue
        if within is not None and not m.startswith(within + '/'): continue
        if needle in t:
            hits.append(m)
    return hits

res = {'cited': [0, 0], 'uncited': [0, 0], 'dironly': [0, 0]}
by_sub = collections.defaultdict(lambda: {'cited': [0, 0], 'uncited': [0, 0]})
uncited_list = []
for p, f in files.items():
    if f['cat'] != 'RECORDS':
        continue
    b = os.path.basename(p)
    ud = unit_dir(p)
    rel_unit = p[len(ud) + 1:]            # e.g. probes/walk.txt
    unit_name = os.path.basename(ud)      # e.g. rung-timing
    suffix = unit_name + '/' + rel_unit   # e.g. rung-timing/probes/walk.txt
    lines = f['lines_at_landing'] if f['lines_at_landing'] is not None else f['add']
    how = None
    if b in COMMON_MD:
        # cited through its directory: the unit dir named in a .md outside the unit dir, or path suffix anywhere
        if any_md(suffix, exclude=(p,)):
            how = 'path'
        elif ud == os.path.dirname(p) and any_md(unit_name, exclude=(p,)) and \
                [m for m in any_md(unit_name, exclude=(p,)) if not m.startswith(ud + '/')]:
            how = 'dir'
        elif ud != os.path.dirname(p):
            dn = os.path.relpath(os.path.dirname(p), os.path.dirname(ud))
            if any_md(dn, exclude=(p,)):
                how = 'dir'
    elif bn_count[b] <= 1:
        if any_md(b, exclude=(p,)):
            how = 'basename'
    else:
        if any_md(suffix, exclude=(p,)):
            how = 'path'
        elif any_md(rel_unit, exclude=(p,), within=ud):
            how = 'relpath'
    if how is None:
        # directory-only citation (the file's own directory named somewhere)
        dn = os.path.relpath(os.path.dirname(p), os.path.dirname(ud))  # e.g. rung-timing/probes
        if dn != unit_name and any_md(dn + '/', exclude=(p,)):
            res['dironly'][0] += 1; res['dironly'][1] += lines
    key = 'cited' if how else 'uncited'
    res[key][0] += 1; res[key][1] += lines
    by_sub[f['sub']][key][0] += 1; by_sub[f['sub']][key][1] += lines
    if not how:
        uncited_list.append((lines, p))
    elif verbose:
        print('CITED', how, p)

print(d['name'], json.dumps(res))
for k, v in by_sub.items():
    print('  ', k, json.dumps(v))
uncited_list.sort(reverse=True)
print('uncited top 15:')
for l, p in uncited_list[:15]:
    print('  ', l, p)
cnt = collections.Counter(unit_dir(p) for l, p in uncited_list)
print('uncited by unit dir:', dict(cnt))

